#include <stddef.h>

void compress_string(const char *src, char *dest)
{
    const char *p = src;

    while (*p) {
        char c = *p;
        int count = 0;

        while (*p == c) {
            count++;
            p++;
        }

        *dest++ = c;

        if (count >= 10) {
            *dest++ = '0' + count / 10;
            *dest++ = '0' + count % 10;
        } else if (count > 1) {
            *dest++ = '0' + count;
        }
    }

    *dest = '\0';
}

